class Counter(object):
    def __init__(self):
        self.reset()

    def value(self):
        return self._value

    def increase(self, x):
        self._value += x

    def reset(self):
        self._value = 0


class Timer(object):
    def __init__(self, step=1):
        self._step = step
        self._start = time.time()

    def _diff(self):
        return float(time.time() - self._start)

    def wait(self):
        time.sleep(self._step)

    def expired(self, timeout):
        return self._diff() >= timeout


