    @log_method_name
    def get_hw_type(self):
        temp_dir = ta5g_interface_tools.get_robot_temp_dir()
        if not os.path.isfile('{}/iphy.xml'.format(temp_dir)):
            self.get_iphy_xml_file(output_filepath='{}/iphy.xml'.format(temp_dir))
        iphy_xml = ET.parse(source='{}/iphy.xml'.format(temp_dir))
        l1_bypass = iphy_xml.find(".//L1Bypass")
        if l1_bypass is not None:
            l1_bypass_text = l1_bypass.text.lower()
            if l1_bypass_text in ["true", "t", "1", "yes", "y"]:
                return 'L1B'
        return 'FS'

