    def reset_slave_wts(self, testline_config_index=1):
        pdu_details = self._ta_testline_mgmt.get_testline_pdu_details(testline_config_index)
        pdu_addr, pdu_device, pdu_port = pdu_details[3:]
        logger.console(
            "Resetting Slave Wts  pdu_addr: {} pdu_port: {} pdu_device: {}".format(pdu_addr, pdu_port, pdu_device)
        )
        self._pdu_interface.setup_pdu(alias='iphy', host=str(pdu_addr), model=str(pdu_device))
        self._pdu_interface.reset_ports(pdu_device='iphy', ports=[pdu_port])

    @saneconsole
    @log_method_name
    def reset_wts_and_wait_for_enb_to_reach_configured_state(self, output_dirpath=None):
        output_dirpath = self.__get_output_dir(output_dirpath)
        try:
            self._ta_syslog.start_syslog_for_enb(
                logs_dirpath='{}/reset_iphy_enb_syslog'.format(output_dirpath), alias='reset_iphy_enb_syslog'
            )
            self._ta_syslog.start_syslog_for_iphy(
                logs_dirpath='{}/reset_iphy_iphy_syslog'.format(output_dirpath), alias='reset_iphy_iphy_syslog'
            )
            self.reset_wts()
            self.check_radios_availability()
        finally:
            self._ta_syslog.stop_syslog_with_specified_alias(alias='reset_iphy_enb_syslog')
            self._ta_syslog.stop_syslog_with_specified_alias(alias='reset_iphy_iphy_syslog')

    @log_method_name
    def verify_that_given_number_of_radio_modules_is_up(self, connection_handler, rmod_count):
        """
        :param connection_handler:
        :param rmod_count:
        """
        count = self._get_number_of_enabled_radio_modules(connection_handler)
        logger.info('verify_that_given_number_of_radio_modules_is_up')
        rmod_count = int(rmod_count)
        logger.info('number of radios available current: {} vs expected: {}'.format(count, rmod_count))
        return count == rmod_count

    def _get_number_of_enabled_radio_modules(self, connection):
        return len([radio for radio in connection.get_frm() if radio['status']['operationalState'].lower() == 'enabled'])

    @saneconsole
    @log_method_name
    def wait_until_given_number_of_radio_modules_is_up(self, rmod_count, timeout=1200, alias='check_for_rmods', remote_hosts=None):
        """
        :param rmod_count: number of radio modules
        :param timeout:
        :param alias:
        :return:
        """
        logger.console('Waiting {}s until {} radio modules are up.'.format(timeout, rmod_count))
        rmod_count = self._count_expected_radio_modules(rmod_count)
        enabled_radios = Counter()
        timer = Timer()

        while int(rmod_count) != int(enabled_radios.value()) and not timer.expired(timeout):
            enabled_radios.reset()
            self._count_enabled_local_radio_modules(enabled_radios)
            self._count_enabled_remote_radio_modules(enabled_radios, remote_hosts)
            timer.wait()

        if int(rmod_count) != int(enabled_radios.value()):
            raise AssertionError("Wrong number of enabled radio modules. Expected: {} Got: {}".format(rmod_count, enabled_radios.value()))

    def _count_expected_radio_modules(self, rmod_count):
        if isinstance(rmod_count, str):
            logger.console('string rmod_count {}'.format(rmod_count))
            if '=' in rmod_count:
                rmod_count = int(rmod_count.split('=')[1])
        return rmod_count

    def _count_enabled_local_radio_modules(self, enabled_radios):
        with ta_admin_interface.admin_interface() as connection:
            enabled_radios.increase(self._get_number_of_enabled_radio_modules(connection))
            logger.console("Num of enabled radio modules: {}".format(enabled_radios.value()))

    def _count_enabled_remote_radio_modules(self, enabled_radios, remote_hosts=None):
        if remote_hosts is not None:
            for remote_host in remote_hosts:
                with ta_admin_interface.remote_admin_interface(remote_host) as connection:
                    enabled_radios.increase(self._get_number_of_enabled_radio_modules(connection))
                    logger.console("Num of enabled radio modules: {}".format(enabled_radios.value()))

    @saneconsole
    @log_method_name
    def check_radios_availability(self, alias='check_for_rmods', remote_hosts=None):
        self._ta_testline_mgmt.wait_for_testline_icmp_echo_replies_and_ssh_services()
        rmod_count = self.get_rmod_count_from_iphy()
        self.wait_until_given_number_of_radio_modules_is_up(rmod_count=rmod_count, alias=alias, remote_hosts=remote_hosts)

    @saneconsole
    @log_method_name
    def check_radios_availability_multi_ap(self, alias='check_for_rmods_multi_ap', remote_hosts=None, iphy_lmp_ips=[IPHY0_LMP_IP]):
        """
        iphy_lmp_ips: list of AP Ips
        :return:
        """
        total_number_of_radios_on_multiple_ap = 0
        self._ta_testline_mgmt.wait_for_testline_icmp_echo_replies_and_ssh_services()
        for ap in iphy_lmp_ips:
            rmod_count = self.get_rmod_count_from_iphy(remote_host=remote_hosts, iphy_lmp_ip=ap)
            total_number_of_radios_on_multiple_ap += rmod_count
        self.wait_until_given_number_of_radio_modules_is_up(rmod_count=total_number_of_radios_on_multiple_ap, alias=alias, remote_hosts=remote_hosts)

    @log_method_name
    def get_rmod_count_from_iphy(self, remote_host=None, iphy_lmp_ip=IPHY0_LMP_IP):
        temp_dir = get_robot_temp_dir()
        self.get_iphy_xml_file(
            output_filepath='{}/iphy.xml'.format(temp_dir), iphy_lmp_ip=iphy_lmp_ip, remote_host=remote_host
        )
        iphy_xml = ET.parse(source='{}/iphy.xml'.format(temp_dir))
        rrh_count = len(iphy_xml.findall(path='.//RRH'))
        re_count = len(iphy_xml.findall(path='.//RE'))
        rmod_count = rrh_count + re_count
        logger.info("rmod count: {}".format(rmod_count))
        return rmod_count

    @log_method_name
    def reset_wts_and_wait_until_all_radio_modules_are_enabled(self):
        self.reset_wts()
        self.check_radios_availability()

    @log_method_name
    def multi_enb_wait_until_all_radio_modules_are_enabled(self, remote_host_list=None):
        IPHY_LMP_LIST = [IPHY0_LMP_IP, IPHY1_LMP_IP, IPHY2_LMP_IP]
        self._ta_testline_mgmt.multi_enb_wait_till_testline_lmp_interfaces_become_pingable(remote_host_list)
        for host, iphy_lmp_ip in zip(remote_host_list, IPHY_LMP_LIST):
            rmod_count = self.get_rmod_count_from_iphy(remote_host=host, iphy_lmp_ip=iphy_lmp_ip)
            self.wait_until_given_number_of_radio_modules_is_up(rmod_count=rmod_count)

    def get_iphy_snapshot(self, remote_host=None, output_filepath=None, iphy_ip=IPHY0_LMP_IP, all_nodes=False):
        """
        Experimental keyword.
        Please note that using all_nodes option, execution may takes about 40 minutes.
        :param iphy_ip:
        :param output_filepath:
        :param remote_host:
        :param all_nodes: collect logs from all nodes
        """
        logger.console("Starting collecting iphy snapshot")
        if iphy_ip == IPHY0_LMP_IP:  # tmp fix for multi enb test runs
            filename, output_filepath = self._prepare_output_data_for_snapshot_collection(output_filepath)
            try:
                aashell_log_instance = aashell_log()
                aashell_cli_instance = aashell_cli()
                core_instance = core()
                airphone = {'host': IPHY0_LMP_IP, 'user': 'toor4nsn', 'password': 'oZPS0POrRieRtu'}
                aashell_cli_instance.create_aashell_cli(name='aashell_cli', hops=airphone)
                aashell_log_instance.create_aashell_log_collector(name=output_filepath, tool='aashell_cli',
                                                                  target_file_name=filename, timeout=300)
                core_instance.setup_collectors(names=output_filepath)
                core_instance.collect_collectors(names=output_filepath, target_dir=output_filepath)
            except Exception as exc:
                exception_trace = traceback.format_exc()
                logger.info("Following error occured during geting iphy_snapshot:\n{}".format(exception_trace))
                raise exc
            finally:
                core_instance.teardown_collectors(names=output_filepath)

    def _prepare_output_data_for_snapshot_collection(self, output_filepath):
        if not output_filepath:
            filename = 'iphy_snapshot.zip'
            output_filepath = get_robot_output_dir()
        else:
            try:
                filename = output_filepath.split("/")[-1]
                if 'zip' not in filename and 'tgz' not in filename:
                    logger.console("No valid output_filepath available")
                    raise Exception
                output_filepath = output_filepath.replace(filename, "")
            except Exception:
                logger.console("Iphy Snapshot logs will be collected in OUTPUTDIR in iphy_snapshot.zip")
                filename = 'iphy_snapshot.zip'
                output_filepath = get_robot_output_dir()
        return filename, output_filepath

    @staticmethod
    def __prepare_and_run_aashell_command(filename, all_nodes, iphy_ip):
        cmd = 'log -z {}'.format(filename)
        timeout = 20
        if all_nodes:
            cmd += ' -a'
            timeout = None
        execute_aashell_command(command=cmd, enb_ip=iphy_ip, command_timeout=timeout)

