    @log_method_name
    def check_radios_availability_aic(self, timeout=30, number_of_vdu=1):
        """
        Checking radios availability in given number of vdu aic
        :param timeout: by default set to 30 seconds
        :param number_of_vdu: number of vdu, by default set to 1
        :return:
        """
        logger.console("Checking radio availabilty for {} vdu started".format(number_of_vdu))
        self.wait_for_all_radios_to_be_enabled_aic(timeout=timeout, number_of_vdu=int(number_of_vdu))

    def check_all_rmods_enabled_aic(self, number_of_vdu=1):
        """
        Checking if all rmods are enabled in given number of vdu aic
        :param number_of_vdu: number of vdu, by default set to 1
        :return:
        """
        for vdus in range(number_of_vdu):
            self.check_all_rmods_enabled_in_one_vdu_aic(host=self.get_vdu_master_ip(vdu=vdus))

    def check_all_rmods_enabled_in_one_vdu_aic(self, host='192.168.255.129'):
        """
        Checking if all rmods are enabled in one vdu aic
        :param host: oam ip of vdu
        :return:
        """
        with ta5g_admin_operations().connect_to_vdu_aic(host) as vdu_connection:
            rmods_statuses = vdu_connection.get_rmods_status()
            for radio in rmods_statuses:
                radio_id = radio['id']
                actual = radio['operational_state'].lower()
                logger.console("Radio in vdu {} with id {} is {}".format(host, radio_id, actual))
                ta5g_admin_operations().assert_equal(
                    expected='enabled', actual=actual,
                    message="Radio with id {} is {}\nRadio should be enabled".format(radio['id'], actual))

    def wait_for_all_radios_to_be_enabled_aic(self, timeout=30, number_of_vdu=1):
        """
        Waits for radios to be enabled aic
        :param timeout: by default set to 30 seconds
        :param number_of_vdu: number of vdu, by default set to 1
        :return:
        """
        logger.console("Waiting {} seconds for all radio modules to be enabled.".format(timeout))
        ta5g_admin_operations().check_until_timeout(checking_func=self.check_all_rmods_enabled_aic, timeout=timeout, number_of_vdu=number_of_vdu)

    def get_vdu_master_ip(self, vdu=0):
        tl = BuiltIn().get_variable_value("${tl}")
        return tl.gnbs[0].dus[vdu].oam_http_connection_details.addr

    def lock_radio_aic(self, rmod=1, vdu=1, timeout=300):
        with ta5g_admin_operations().connect_to_vdu_aic(host=self.get_vdu_master_ip(vdu=int(vdu)-1)) as vdu_connection:
            lock_rmod = vdu_connection.lock_rmods(rmod_id_list=[str(rmod)], timeout=int(timeout))
            logger.console("Locking radio {} on VDU {}".format(rmod, vdu))
            start_time = time.time()
            while time.time() - start_time < int(timeout):
                operation_state = vdu_connection.get_operation_state_of_locking_rmods(lock_rmod['id'])
                if operation_state['status'] == 'success':
                    break
                time.sleep(10)
            if operation_state['status'] != 'success':
                raise Exception("Locking radio {} on VDU {} failed after {} seconds".format(rmod, vdu, timeout))

    def unlock_radio_aic(self, rmod=1, vdu=1, timeout=300):
        with ta5g_admin_operations().connect_to_vdu_aic(host=self.get_vdu_master_ip(vdu=int(vdu)-1)) as vdu_connection:
            unlock_rmod = vdu_connection.unlock_rmods(rmod_id_list=[str(rmod)], timeout=int(timeout))
            logger.console("Unlocking radio {} on VDU {}".format(rmod, vdu))
            start_time = time.time()
            while time.time() - start_time < int(timeout):
                operation_state = vdu_connection.get_operation_of_unlocking_rmods(unlock_rmod['id'])
                if operation_state['status'] == 'success':
                    break
                time.sleep(10)
            if operation_state['status'] != 'success':
                raise Exception("Unlocking radio {} on VDU {} failed after {} seconds".format(rmod, vdu, timeout))

    def reset_radio_aic(self, rmod=1, vdu=1, timeout=300):
        with ta5g_admin_operations().connect_to_vdu_aic(host=self.get_vdu_master_ip(vdu=int(vdu)-1)) as vdu_connection:
            rmod = vdu_connection.reset_rmods(rmods_list=[1])
            logger.console("Resetting radio {} on VDU {}".format(rmod, vdu))
            start_time = time.time()
            while time.time() - start_time < int(timeout):
                operation_state = vdu_connection.get_reset_rmods_operation_status(operation_id=rmod['operation_id'])
                if operation_state['status'] == 'success':
                    break
                time.sleep(10)
            if operation_state['status'] != 'success':
                raise Exception("Resetting radio {} on VDU {} failed after {} seconds".format(rmod, vdu, timeout))
